 const root=new DOMParser().parseFromString('<div>'+(i.body||'')+'</div>','text/html').body.firstChild,tx=n=>(n&&n.textContent||'').replace(/\s+/g,' ').trim(),
 kill=n=>{if(!n)return;const p=n.previousElementSibling;if(p&&/^H[1-4]$/.test(p.tagName))p.remove();n.remove()};
 if(t==='service'){const g=root.querySelector('.sv-grid');if(g)o.steps=[...g.children].slice(0,4).map(c=>[tx(c.querySelector('b')||c),tx(c.querySelector('p'))]);
  o.chips=[...root.querySelectorAll('.sv-chips span')].slice(0,2).map(tx);kill(g);const c=root.querySelector('.sv-chips');if(c)c.remove();const l=root.querySelector('.sv-lead');if(l)l.remove();o.menu=o.steps.map(s=>shortT(s[0],18))}
