 if(lr.length){if('IntersectionObserver'in window&&!red){const io=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add('in');if(x.target.classList.contains('lp-lap'))run(x.target);io.unobserve(x.target)}}),{threshold:.15,rootMargin:'0px 0px -40px 0px'});lr.forEach((e,k)=>{if(!e.style.getPropertyValue('--i'))e.style.setProperty('--i',k%4);io.observe(e)})}else lr.forEach(e=>{e.classList.add('in');if(e.classList.contains('lp-lap'))run(e)})}
